import SwiftUI
struct JobCardView: View { let job: Job; @State private var expanded=false; var body: some View { GeometryReader { proxy in VStack(alignment:.leading,spacing:0){top.frame(height:expanded ? proxy.size.height*0.22 : proxy.size.height*0.40); middle.frame(height:expanded ? proxy.size.height*0.28 : proxy.size.height*0.40); bottom.frame(maxHeight:.infinity,alignment:.top)}.padding(22).frame(maxWidth:.infinity,maxHeight:expanded ? proxy.size.height : proxy.size.height*0.72).background(RoundedRectangle(cornerRadius:DS.Radius.xl).fill(DS.ColorToken.surface)).overlay(RoundedRectangle(cornerRadius:DS.Radius.xl).stroke(DS.ColorToken.border.opacity(0.55),lineWidth:1)).shadow(color:.black.opacity(0.12),radius:20,x:0,y:12).onTapGesture{withAnimation(.cardPeel){expanded.toggle()}} }.padding(.horizontal,DS.Spacing.md) }
    private var top: some View { HStack(alignment:.top){ Circle().fill(Color(hex:job.logoColor)).frame(width:68,height:68).overlay(Text(String(job.company.prefix(1))).font(.system(size:30,weight:.bold)).foregroundStyle(.white)); Spacer(); Text("\(job.matchScore)% match").font(DS.FontToken.label).foregroundStyle(.white).padding(.horizontal,12).padding(.vertical,7).background(Capsule().fill(DS.ColorToken.primary)) } }
    private var middle: some View { VStack(alignment:.leading,spacing:10){ Text(job.role).font(.system(size:22,weight:.bold)).foregroundStyle(DS.ColorToken.text).fixedSize(horizontal:false,vertical:true); Text(job.company).font(DS.FontToken.body).foregroundStyle(DS.ColorToken.textMuted); Text([job.location,job.salary].compactMap{$0}.joined(separator:"  •  ")).font(DS.FontToken.caption).foregroundStyle(DS.ColorToken.textFaint); ScrollView(.horizontal,showsIndicators:false){HStack{ForEach(job.tags,id:\.self){tag in Text(tag).font(DS.FontToken.caption).foregroundStyle(DS.ColorToken.textMuted).padding(.horizontal,8).padding(.vertical,6).background(RoundedRectangle(cornerRadius:DS.Radius.sm).fill(DS.ColorToken.surfaceOffset))}}} } }
    private var bottom: some View { VStack(alignment:.leading,spacing:12){ Divider().overlay(DS.ColorToken.border); Text(job.description).font(DS.FontToken.body).foregroundStyle(DS.ColorToken.text).lineLimit(expanded ? nil : 2); if expanded { Text("Requirements").font(DS.FontToken.label); VStack(alignment:.leading,spacing:6){Text("• Experience building reliable user-facing software"); Text("• Strong collaboration with design, product, and engineering"); Text("• Clear written communication and ownership mindset")}.font(DS.FontToken.caption).foregroundStyle(DS.ColorToken.textMuted); Button("Apply with tailored resume"){HapticManager.shared.trigger()}.buttonStyle(.borderedProminent).tint(DS.ColorToken.primary) }; Text(expanded ? "Tap to collapse" : "Tap to expand").font(DS.FontToken.caption).foregroundStyle(DS.ColorToken.textFaint) } }
}
